import NavLink from '@/components/common/NavLink'
import ConnectButton from '@/components/wallet/ConnectButton'
import { isMenuActive } from '@/utils'
import { useJump2Dex } from '@cetus/hooks/src/useJump2Dex'
import { BackButton, Drawer, Icon, SwitchChain } from '@cetus/ui-kit'
import { Box, Flex, HStack, Image, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import { useLocation } from 'react-router-dom'
import H5Settings from '../settings/h5'
import { ChildMenuItem, IMenusProps, MenuItemWithChildren, MenuItemWithoutChildren } from '../type'
const H5Header = ({ menus, logo, setting, notifications, chain, jump, isCetusPump }: IMenusProps) => {
  const [menuOpen, setMenuOpen] = useState<boolean>(false)
  const { back2Dex } = useJump2Dex()
  return (
    <>
      <Flex w="100%" justifyContent="space-between" align="center" p="0px 8px" h="48px">
        <Image src="/images/img-logo@2x.png" h="32px" alt="logo" onClick={() => jump('/')} />
        <Flex align="center" gap="8px">
          {chain && <SwitchChain {...chain} />}
          {isCetusPump && <BackButton w="114px" h="36px" text="Back to DEX" onClick={() => jump('/')} />}
          <ConnectButton isCetusPump={isCetusPump} />
          {/* {notifications && <Notifications {...notifications} />} */}
          <Box
            w="36px"
            h="36px"
            p="7px"
            bg="bg_secondary"
            borderRadius="8px"
            border="1px solid"
            borderColor="border"
            cursor="pointer"
            _hover={{ bg: 'menu_item_hover_bg' }}
          >
            <Icon xlinkHref="#icon-icon_menu" onClick={() => setMenuOpen(!menuOpen)} />
          </Box>
        </Flex>
      </Flex>
      <H5Menu
        menus={menus}
        setting={setting}
        title={<Image src={logo.image} h="32px" alt="logo" onClick={() => jump(logo.url)} />}
        isOpen={menuOpen}
        onClose={() => setMenuOpen(false)}
        jump={jump}
        isCetusPump={isCetusPump}
      />
    </>
  )
}

interface IH5MenuProps extends Omit<IMenusProps, 'notifications' | 'logo' | 'chain'> {
  title: React.ReactNode
  isOpen: boolean
  onClose: () => void
}

const H5Menu = ({ menus, setting, title, isOpen, onClose, jump, isCetusPump }: IH5MenuProps) => {
  const { pathname } = useLocation()
  const more = menus?.find(menu => !!(menu as any)?.socials)
  const [openList, setOpenList] = useState<string[]>([])

  const handleMenuVisible = (title: string) => {
    if (openList.includes(title)) {
      setOpenList(openList.filter(item => item !== title))
    } else {
      setOpenList([...openList, title])
    }
  }

  useEffect(() => {
    onClose()
  }, [pathname])

  return (
    <Drawer title={title} isOpen={isOpen} onClose={onClose} placement="left" size="full">
      <VStack w="100%" h="100%" justify="space-between">
        <VStack gap="36px" w="100%" align="flex-start" mt="32px">
          {menus.map(menu => {
            if ((menu as any).children) {
              const active = isMenuActive(menu as any, pathname)
              return (
                <Box key={menu.title} w="100%">
                  <HStack
                    onClick={() => handleMenuVisible(menu.title)}
                    sx={{
                      p: {
                        color: active ? 'text_caption' : 'text_paragraph'
                      },
                      svg: {
                        fill: active ? 'text_caption' : 'text_paragraph'
                      }
                    }}
                    _hover={{
                      p: {
                        color: 'text_caption'
                      },
                      svg: {
                        fill: 'text_caption'
                      }
                    }}
                  >
                    <Text fontSize="16px">{menu.title}</Text>
                    <Icon
                      xlinkHref="#icon-icon_arrow"
                      fontSize="16px"
                      variant="gray"
                      svgFill="primary_gray"
                      transition="transform 0.5s"
                      transform={openList.includes(menu.title) ? 'rotate(180deg)' : 'rotate(0deg)'}
                    />
                  </HStack>
                  {openList.includes(menu.title) && (
                    <VStack
                      mt="12px"
                      bg="bg_secondary"
                      gap="24px"
                      p="20px 16px"
                      w="100%"
                      align="flex-start"
                      border="1px solid"
                      borderColor="border"
                      borderRadius="8px"
                    >
                      {(menu as MenuItemWithChildren).children?.map(item => {
                        const childActive = isMenuActive(item as any, pathname)
                        return <Item key={item.title} item={item} jump={jump} isActive={childActive} />
                      })}
                    </VStack>
                  )}
                </Box>
              )
            }
            return (
              <NavLink
                key={menu.title}
                link={(menu as MenuItemWithoutChildren).path}
                isActive={isMenuActive(menu as MenuItemWithoutChildren, pathname)}
              >
                <Text color="inherit" fontSize="16px" fontWeight="500">
                  {menu.title}
                </Text>
              </NavLink>
            )
          })}
        </VStack>
        <VStack w="100%">
          <H5Settings {...setting} isCetusPump={isCetusPump} />

          <HStack w="100%">
            {more &&
              (more as MenuItemWithChildren)?.socials &&
              (more as MenuItemWithChildren)?.socials?.map(social => {
                return (
                  <Flex
                    key={social.title}
                    flex="1"
                    onClick={() => window.open(social.path)}
                    padding="14px"
                    h="48px"
                    borderRadius="8px"
                    border="1px solid"
                    borderColor="border"
                    bg="menu_item_bg"
                    justify="center"
                    align="center"
                    _hover={{
                      p: {
                        color: 'text_caption'
                      },
                      svg: {
                        fill: 'text_caption'
                      }
                    }}
                  >
                    {social.icon ? (
                      <Box>
                        {typeof social.icon === 'string' ? (
                          <Icon xlinkHref={social.icon} variant="gray" />
                        ) : (
                          <Icon xlinkHref={social.icon.xlinkHref} variant="gray" />
                        )}
                      </Box>
                    ) : null}
                  </Flex>
                )
              })}
          </HStack>
        </VStack>
      </VStack>
    </Drawer>
  )
}

interface ItemProps {
  item: ChildMenuItem
  jump: (path: string) => void
  isActive: boolean
}

const Item = ({ item, jump, isActive }: ItemProps) => {
  const [open, setOpen] = useState(false)
  return (
    <>
      <HStack
        key={item.title}
        justify="space-between"
        h="20px"
        lineHeight="20px"
        onClick={() =>
          item?.children && item?.children?.length > 1
            ? setOpen(!open)
            : item?.type === '_blank'
              ? window.open(item.path, '_blank')
              : jump((item as ChildMenuItem).path)
        }
        sx={{
          p: {
            color: isActive ? 'text_caption' : 'text_paragraph'
          },
          svg: {
            fill: isActive ? 'text_caption' : 'text_paragraph'
          }
        }}
        _hover={{
          p: {
            color: 'text_caption'
          },
          svg: {
            fill: 'text_caption'
          }
        }}
      >
        <HStack>
          <Icon xlinkHref={(item as ChildMenuItem)?.icon as string} variant="gray" />
          <Text color="inherit" fontSize="16px" fontWeight="500">
            {item.title}
          </Text>
        </HStack>
        {item.children && item.children.length > 0 && (
          <Icon
            xlinkHref="#icon-icon_arrow"
            fontSize="16px"
            variant="gray"
            svgFill="primary_gray"
            transition="transform 0.5s"
            transform={open ? 'rotate(180deg)' : 'rotate(0deg)'}
          />
        )}
      </HStack>
      {open &&
        item.children &&
        item.children.length > 0 &&
        item.children?.map(child => <Item key={child.title} item={child} jump={jump} isActive={false} />)}
    </>
  )
}

export default H5Header
