import { SettingProps } from '../type'
import H5Language from './Language'
import H5Preferred from './Preferred'
import H5RPCNode from './RPCNode'
interface H5Settings extends SettingProps {
  isCetusPump: boolean
}
const H5Settings = ({ language, preferred, rpcNode, isCetusPump }: H5Settings) => {
  return (
    <>
      <H5RPCNode {...rpcNode} />
      <H5Preferred value={preferred.value} options={preferred.options} onValueChange={value => preferred.onValueChange(value)} />
      {!isCetusPump && <H5Language value={language.value} options={language.options} onValueChange={value => language.onValueChange(value)} />}
    </>
  )
}
export default H5Settings
