import { VStack } from '@chakra-ui/react'
import { useState } from 'react'
import ListItem from '../ListItem'
import { IH5temSettingInterface } from '../type'
import H5SettingItem from './Item'

const H5Language = ({ value, onValueChange, options }: IH5temSettingInterface) => {
  const [showOptions, setShowOptions] = useState(false)
  return (
    <>
      <H5SettingItem icon="#icon-icon_language" label="Language" value={value} onClick={() => setShowOptions(!showOptions)} />
      {showOptions && (
        <VStack w="100%">
          {options.map(item => {
            return <ListItem key={item} label={item} value={item} isActive={item === value} onClick={() => onValueChange(item)} />
          })}
        </VStack>
      )}
    </>
  )
}

export default H5Language
