import {
  Drawer as BaseDrawer,
  Button,
  DrawerBody,
  DrawerCloseButton,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerOverlay,
  DrawerProps
} from '@chakra-ui/react'

interface IDrawerProps extends DrawerProps {
  title: React.ReactNode
  footer?: React.ReactNode | boolean
  cancelText?: string
  okText?: string
  onSubmit?: () => void
}

export default function Drawer({ title, isOpen, onClose, children, cancelText, okText, onSubmit, footer = false, placement, size }: IDrawerProps) {
  return (
    <BaseDrawer isOpen={isOpen} placement={placement || 'right'} onClose={onClose} size={size || 'md'}>
      <DrawerOverlay />
      <DrawerContent>
        <DrawerCloseButton />
        <DrawerHeader>{title}</DrawerHeader>

        <DrawerBody>{children}</DrawerBody>

        <DrawerFooter>
          {typeof footer !== 'boolean'
            ? footer
            : footer && (
                <>
                  <Button variant="outline" mr={3} onClick={onClose}>
                    {cancelText}
                  </Button>
                  <Button colorScheme="blue" onClick={onSubmit}>
                    {okText}
                  </Button>
                </>
              )}
        </DrawerFooter>
      </DrawerContent>
    </BaseDrawer>
  )
}
